	// NOTE: With `k_vec ^ i_vec` and `scalar ^ tuning.a_layout`,
	//       the resulting structure is row-major in (i,k): `i` is
	//       the outer dimension, `k` the inner / contiguous one.
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

