	beta = (num_t)1.2;

	// A[i][k] = ( (i * k + 1) % n ) / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto n_len = A | get_length<'i'>();
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto m_len = A | get_length<'k'>(); // use A's second dimension length (M)
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// Original BLAS SYRK (lower triangle):
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), only j <= i is updated
//
// The original implementation did:
//
//   for i, j:
//     if j <= i: C[i,j] *= beta
//   for i, j, k:
//     if j <= i: C[i,j] += alpha * A[i,k] * A[j,k]
//
// Here we:
//   * fuse the beta-scaling and the accumulation into a single pass over C,
//   * block (tile) the i, j, and k dimensions using `into_blocks_dynamic`,
//   * traverse tiles in a cache-friendly order with `for_dims`,
//   * keep a scalar accumulator `c_ij` in a register for each (i,j) over k.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// Tunable tile sizes; chosen conservatively so they work well
	// on typical x64 cache hierarchies. They can be adjusted.
	constexpr std::size_t TI = 32; // tile size in i
	constexpr std::size_t TJ = 32; // tile size in j
	constexpr std::size_t TK = 64; // tile size in k (reduction dim)

	// Build a proto-structure that:
	//   - splits i  into (I, i) with presence guard 'r',
	//   - splits j  into (J, j) with presence guard 's',
	//   - splits k  into (K, k) with presence guard 't'.
	//
	// `into_blocks_dynamic` allows the last tile to be partial; the extra
	// dimension ('r', 's', 't') has length 1 for valid elements and 0 for
	// dummy elements past the original length. We include these guard
	// dimensions in `for_dims` so that invalid indices are never visited.
	auto blocking =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(TI) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(TJ) ^
		noarr::into_blocks_dynamic<'k', 'K', 'k', 't'>(TK);

	#pragma scop
	noarr::traverser(C, A)
		// Reorder traversal using the blocked view, but still expose
		// states in terms of the original dimensions (i,j,k).
		.order(blocking)
		// Outer tile loop over I (i-tiles)
		.template for_dims<'I'>([=](auto trav_I) {
			// Next outer tile loop over J (j-tiles)
			trav_I.template for_dims<'J'>([=](auto trav_J) {
				// Inside a (I,J) tile, iterate over valid i's.
				// Including 'r' ensures that partial tiles are handled
				// correctly (no out-of-bounds indices).
				trav_J.template for_dims<'i', 'r'>([=](auto trav_i) {
					// For each i in this tile, iterate over valid j's in
					// the tile. Including 's' handles partial j-tiles.
					trav_i.template for_dims<'j', 's'>([=](auto trav_ij) {
						// `trav_ij.state()` gives a state expressed only in
						// the original dimensions ('i', 'j', 'k'); the
						// blocking dimensions ('I','J','K','r','s','t') are
						// used only internally by the traverser.
						auto state_ij = trav_ij.state();
						auto [i_idx, j_idx] = get_indices<'i', 'j'>(state_ij);

						// Respect the lower-triangular domain: only update
						// C[i,j] when j <= i. The upper triangle is left
						// unchanged, matching the original kernel.
						if (j_idx > i_idx)
							return;

						// Fused beta-scaling + rank-k accumulation:
						//   c_ij = beta * C[i,j]
						//   c_ij += alpha * sum_k A[i,k] * A[j,k]
						//   C[i,j] = c_ij
						//
						// We keep `c_ij` as a scalar accumulator in a
						// register across all k for this (i,j).
						num_t c_ij = C[trav_ij] * beta;

						// Iterate over k-tiles K and then over k within
						// each tile. Including 't' in the blocking proto
						// ensures we skip any out-of-range k's.
						trav_ij.template for_dims<'K'>([&](auto trav_K) {
							// for_each here iterates over the remaining
							// unfixed dimensions, which are exactly k +
							// its presence guard 't' after the previous
							// for_dims calls.
							trav_K.for_each([&](auto state_k) {
								// `state_k` contains (i,j,k) in the
								// original coordinate system; 't' is
								// not visible here, but its effect is
								// that invalid k's are never visited.

								// A[i,k]: use current state's i,k
								num_t a_ik = A[state_k];

								// A[j,k]: build a state with the same k
								// but with i replaced by j.
								auto state_jk =
									noarr::update_index<'i'>(state_k, [=](auto) { return j_idx; });
								num_t a_jk = A[state_jk];

								c_ij += alpha * a_ik * a_jk;
							});
						});

						// Final store of the accumulated value.
						C[trav_ij] = c_ij;
					});
				});
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
