//
//   - Fuse scaling and accumulation so that each C[i,j] is loaded once,
//     accumulated entirely in a register, and then stored once.
//   - Process C row by row (outer loop over i), but within each row use a
//     small j-tiling and a stack buffer rowC[ ] to hold C[i, j_block].
//   - For each (i, k) we precompute aik = alpha * A[i,k] once and reuse it
//     when updating all j in the current j-tile.
//   - Access A[j,k] in the inner j loop: since A is k-major, i-inner, varying
//     j (which plays the role of i) at fixed k is unit-stride -> good locality.
//
// C's layout (j-major) still implies that accesses to C[i,j] are strided in
// memory, but we reduce them from O(N^2 * M) to O(N^2) by buffering rows.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// Tunable tile sizes (chosen conservatively; can be retuned per target).
	// J_BLOCK : how many columns j of C[i, j] we process at once for a fixed i.
	// K_BLOCK : how many k-values we process at once inside the reduction.
	constexpr std::size_t J_BLOCK = 64;
	constexpr std::size_t K_BLOCK = 64;

	// Problem sizes (N: dimension of C, M: inner dimension of A).
	const std::size_t N = C | get_length<'i'>();
	const std::size_t M = A | get_length<'k'>();

	#pragma scop
	// Traverse rows i using a Noarr traverser; each iteration fixes index i.
	noarr::traverser(C, A).template for_dims<'i'>([&](auto trav_i) {
		// Extract current row index i from the traverser state.
		auto state_i = trav_i.state();
		const std::size_t i = noarr::get_index<'i'>(state_i);

		// Only lower triangle j <= i is updated. We cover j in tiles.
		for (std::size_t j_block_start = 0; j_block_start <= i; j_block_start += J_BLOCK) {
			// Compute the [j_block_start, j_block_end) interval for this tile,
			// clipped to [0, i+1) to stay within the lower triangle.
			std::size_t j_block_end = j_block_start + J_BLOCK;
			if (j_block_end > i + 1)
				j_block_end = i + 1;
			const std::size_t jb_len = j_block_end - j_block_start;

			// Scratch buffer for the current segment of row i:
			//   rowC[jj] holds C[i, j_block_start + jj] for 0 <= jj < jb_len.
			// We keep it on the stack with a fixed upper bound for simplicity
			// and good compiler vectorization.
			num_t rowC[J_BLOCK];

			// 1) Load and scale C by beta into the row buffer.
			for (std::size_t jj = 0; jj < jb_len; ++jj) {
				const std::size_t j = j_block_start + jj; // global j, guaranteed j <= i
				auto state_ij = noarr::idx<'i', 'j'>(i, j);
				rowC[jj] = beta * C[state_ij];
			}

			// 2) Accumulate alpha * A[i,k] * A[j,k] over k, in tiles of size K_BLOCK.
			for (std::size_t k_block_start = 0; k_block_start < M; k_block_start += K_BLOCK) {
				std::size_t k_block_end = k_block_start + K_BLOCK;
				if (k_block_end > M)
					k_block_end = M;

				for (std::size_t k = k_block_start; k < k_block_end; ++k) {
					// Precompute alpha * A[i,k] once for this (i,k) and reuse
					// it across all j in the current j-tile.
					auto state_ik = noarr::idx<'i', 'k'>(i, k);
					const num_t aik = alpha * A[state_ik];

					// For fixed (i,k), A[j,k] is accessed with unit stride as j
					// varies because A is laid out with i as the inner dimension.
					for (std::size_t jj = 0; jj < jb_len; ++jj) {
						const std::size_t j = j_block_start + jj; // still j <= i
						auto state_jk = noarr::idx<'i', 'k'>(j, k);
						const num_t ajk = A[state_jk];

						rowC[jj] += aik * ajk;
					}
				}
			}

			// 3) Store the updated row segment back to C.
			for (std::size_t jj = 0; jj < jb_len; ++jj) {
				const std::size_t j = j_block_start + jj;
				auto state_ij = noarr::idx<'i', 'j'>(i, j);
				C[state_ij] = rowC[jj];
			}
		}

		// For this i, entries with j > i are never touched, preserving the
		// original "lower triangle only" semantics.
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
